const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let local=[];try{const saved=JSON.parse(localStorage.getItem('transferbridge-v1')||'[]');if(Array.isArray(saved))local=saved.filter(x=>x&&typeof x.id==='string'&&Number.isFinite(x.gpa)&&Array.isArray(x.decisions)&&x.decisions.every(d=>Array.isArray(d)&&d.length===2));}catch{}
const records=()=>[...local,...samples];const statuses=['Admitted','Rejected','Waitlisted','Pending'];
const chip=(school,status)=>`<span class="chip ${statuses.includes(status)?status.toLowerCase():''}">${esc(school)}</span>`;
function filtered(){let list=records(),query=$('#search').value.trim().toLowerCase();list=list.filter(r=>['term','major','type','background'].every(k=>!$('#'+k).value||r[k]===$('#'+k).value));if($('#gpa').value){const [a,b]=$('#gpa').value.split('-').map(Number);list=list.filter(r=>r.gpa>=a&&r.gpa<b);}if($('#decision').value)list=list.filter(r=>r.decisions.some(d=>d[1]===$('#decision').value&&(!query||[r.origin,r.major,d[0]].join(' ').toLowerCase().includes(query))));else if(query)list=list.filter(r=>[r.origin,r.major,...r.decisions.map(d=>d[0])].join(' ').toLowerCase().includes(query));if(['high','low'].includes($('#sort').value))list.sort((a,b)=>$('#sort').value==='high'?b.gpa-a.gpa:a.gpa-b.gpa);return list;}
function render(){const all=records(),list=filtered();$('#profile-count').textContent=String(all.length).padStart(2,'0');$('#decision-count').textContent=all.reduce((n,r)=>n+r.decisions.length,0);$('#school-count').textContent=new Set(all.flatMap(r=>r.decisions.map(d=>d[0]))).size;$('#showing').textContent=`Showing ${list.length} of ${all.length} profiles`;$('#cards').innerHTML=list.length?list.map(r=>`<article class="card"><div class="card-top"><span class="term-badge">${esc(r.term)}</span><span class="sample">${r.id.startsWith('s')?'SAMPLE PROFILE':'YOUR LOCAL PROFILE'}</span></div><h3>${esc(r.major)}</h3><p class="origin">${esc(r.origin)}</p><div class="academic"><div class="gpa-number">${r.gpa.toFixed(2)}<small>/ 4.0 GPA</small></div><div class="background">${esc(r.background)}<br>${esc(r.type)}</div></div>${statuses.map(status=>{const d=r.decisions.filter(d=>d[1]===status);return d.length?`<div class="outcome-label">${status.toUpperCase()} · ${d.length}</div><div class="chips">${d.map(d=>chip(...d)).join('')}</div>`:''}).join('')}<div class="card-bottom"><div class="final">FINAL CHOICE<strong>${esc(r.final||'Still deciding')}</strong></div><button class="detail-link" data-id="${esc(r.id)}">View profile ↗</button></div></article>`).join(''):'<div class="empty"><h3>No matching profiles yet.</h3><p>Try a different university or widen your filters.</p><button class="secondary" id="clear-empty">Clear all filters</button></div>';}
function reset(){ $('#filters').reset();$('#search').value='';$('#sort').value='new';render();}
$('#filters').addEventListener('change',render);$('#filters').addEventListener('submit',e=>e.preventDefault());$('#filters').addEventListener('reset',()=>setTimeout(()=>{$('#search').value='';render()},0));$('#search').addEventListener('input',render);$('#sort').addEventListener('change',render);
function showDetail(id){const r=records().find(r=>r.id===id);if(!r)throw Error('Profile not found');$('#detail-body').innerHTML=`<span class="term-badge">${esc(r.term)}</span> <span class="sample">${r.id.startsWith('s')?'Fictional sample':'Saved on this browser'}</span><h2 class="detail-heading">${esc(r.major)}</h2><p class="muted">Shared by ${esc(r.nickname)}</p><div class="detail-grid"><div><small>College GPA</small><strong>${r.gpa.toFixed(2)} / 4.0</strong></div><div><small>Completed credits</small><strong>${esc(r.credits||'Not shared')}</strong></div><div><small>Previous institution</small>${esc(r.origin)}</div><div><small>Background</small>${esc(r.background)} · ${esc(r.type)}</div></div><h3 class="detail-section">Admission decisions</h3>${r.decisions.map(d=>`<div class="decision-line"><span>${esc(d[0])}</span>${chip(d[1],d[1])}</div>`).join('')}<h3 class="detail-section">Final choice</h3><p>${esc(r.final||'Still deciding')}</p><h3 class="detail-section">Behind the numbers</h3><p class="story">${esc(r.story||'No additional story shared.')}</p><p class="muted">Self-reported backgrounds are not a prediction of admission chances.</p>`;if(!$('#details').open)$('#details').showModal();return {id:r.id,major:r.major,gpa:r.gpa};}
$('#cards').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)showDetail(b.dataset.id);if(e.target.id==='clear-empty')reset()});$('.close').onclick=()=>$('#details').close();$('#details').addEventListener('click',e=>{if(e.target===$('#details')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close()}});
function route(){const share=location.hash==='#share';$('#share').hidden=!share;$('#explore').hidden=share;$('#nav-share').classList.toggle('active',share);$('#nav-explore').classList.toggle('active',!share);$('#crumb').textContent=share?'Share my results':'Admission results';}window.addEventListener('hashchange',()=>{route();window.scrollTo(0,0)});
let rowNumber=0;function addRow(){rowNumber++;const row=document.createElement('div');row.className='decision-row';row.innerHTML=`<label for="school-${rowNumber}">University<input id="school-${rowNumber}" class="school-name" required maxlength="100" placeholder="University name"></label><label for="status-${rowNumber}">Decision<select id="status-${rowNumber}" class="school-status">${statuses.map(s=>`<option>${s}</option>`).join('')}</select></label><button type="button" class="remove" aria-label="Remove university">×</button>`;row.querySelector('button').onclick=()=>{if($('#decision-rows').children.length>1)row.remove()};$('#decision-rows').append(row);return row;}
$('#add-school').onclick=()=>addRow().querySelector('input').focus();
$('#share-form').addEventListener('submit',e=>{e.preventDefault();$('#form-error').textContent='';const data=Object.fromEntries(new FormData(e.target));const decisions=[...document.querySelectorAll('.decision-row')].map(row=>[row.querySelector('input').value.trim(),row.querySelector('select').value]);if(!data.nickname.trim()||!data.origin.trim()||decisions.some(d=>!d[0])){$('#form-error').textContent='Please fill in your nickname, institution, and university names.';return}if(new Set(decisions.map(d=>d[0].toLowerCase())).size!==decisions.length){$('#form-error').textContent='Please list each university once.';return}if(data.final.trim()&&!decisions.some(d=>d[0].toLowerCase()===data.final.trim().toLowerCase()&&d[1]==='Admitted')){$('#form-error').textContent='Your final choice must match a university marked Admitted, or leave it blank.';return}const r={...data,nickname:data.nickname.trim(),origin:data.origin.trim(),final:data.final.trim(),gpa:Number(data.gpa),id:'local-'+Date.now(),createdAt:new Date().toISOString(),decisions};try{localStorage.setItem('transferbridge-v1',JSON.stringify([r,...local]));local.unshift(r)}catch{$('#form-error').textContent='Your browser could not save this profile. Please allow local storage and try again.';return}e.target.reset();$('#decision-rows').innerHTML='';addRow();reset();location.hash='explore';$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4500)});
render();route();addRow();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'search_transfer_profiles',description:'Filter visible sample and browser-local transfer profiles by university or major.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},execute(input){if(typeof input?.query!=='string')throw Error('query must be a string');reset();$('#search').value=input.query;location.hash='explore';render();return filtered().map(({id,major,gpa,decisions})=>({id,major,gpa,decisions}))},annotations:{readOnlyHint:false,untrustedContentHint:true}},{name:'open_transfer_profile',description:'Open a transfer profile detail dialog; does not submit data.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},execute(input){if(typeof input?.id!=='string')throw Error('id must be a string');return showDetail(input.id)},annotations:{readOnlyHint:false,untrustedContentHint:true}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}}
